CREATE DATABASE IF NOT EXISTS savora CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE savora;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL UNIQUE, full_name VARCHAR(160) NOT NULL, role VARCHAR(60) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY AUTO_INCREMENT, sku VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, category VARCHAR(100) NOT NULL, unit VARCHAR(30) NOT NULL DEFAULT 'packs', selling_price DECIMAL(12,2) NOT NULL, unit_cost DECIMAL(12,2), active BOOLEAN NOT NULL DEFAULT TRUE, policy_status ENUM('enabled','review','disabled') NOT NULL DEFAULT 'review', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CHECK (selling_price > 0), CHECK (unit_cost IS NULL OR unit_cost >= 0));
CREATE TABLE IF NOT EXISTS locations (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, region VARCHAR(100), address VARCHAR(500), capacity INT NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, CHECK(capacity >= 0));
CREATE TABLE IF NOT EXISTS product_batches (id BIGINT PRIMARY KEY AUTO_INCREMENT, batch_code VARCHAR(100) NOT NULL UNIQUE, product_id BIGINT NOT NULL, manufactured_on DATE, best_before DATE, expiry_date DATE, handling_verified BOOLEAN NOT NULL DEFAULT FALSE, batch_status ENUM('eligible','ineligible','requires_review') NOT NULL DEFAULT 'requires_review', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), CHECK(best_before IS NULL OR manufactured_on IS NULL OR best_before >= manufactured_on));
CREATE TABLE IF NOT EXISTS inventory (id BIGINT PRIMARY KEY AUTO_INCREMENT, batch_id BIGINT NOT NULL, location_id BIGINT NOT NULL, on_hand INT NOT NULL DEFAULT 0, reserved INT NOT NULL DEFAULT 0, safety_stock INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_batch_location(batch_id,location_id), FOREIGN KEY(batch_id) REFERENCES product_batches(id), FOREIGN KEY(location_id) REFERENCES locations(id), CHECK(on_hand >= 0), CHECK(reserved >= 0 AND reserved <= on_hand), CHECK(safety_stock >= 0));
CREATE TABLE IF NOT EXISTS sales (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, location_id BIGINT NOT NULL, sold_on DATE NOT NULL, units_sold INT NOT NULL, unit_price DECIMAL(12,2), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(location_id) REFERENCES locations(id), CHECK(units_sold >= 0), INDEX ix_sales_series(product_id,location_id,sold_on));
CREATE TABLE IF NOT EXISTS incoming_shipments (id BIGINT PRIMARY KEY AUTO_INCREMENT, batch_id BIGINT NOT NULL, location_id BIGINT NOT NULL, quantity INT NOT NULL, expected_at DATETIME NOT NULL, status ENUM('planned','in_transit','received','cancelled') NOT NULL DEFAULT 'planned', FOREIGN KEY(batch_id) REFERENCES product_batches(id), FOREIGN KEY(location_id) REFERENCES locations(id), CHECK(quantity >= 0));
CREATE TABLE IF NOT EXISTS reservations (id BIGINT PRIMARY KEY AUTO_INCREMENT, inventory_id BIGINT NOT NULL, quantity INT NOT NULL, status ENUM('active','released','fulfilled') NOT NULL DEFAULT 'active', reference_code VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(inventory_id) REFERENCES inventory(id), CHECK(quantity >= 0));
CREATE TABLE IF NOT EXISTS inventory_movements (id BIGINT PRIMARY KEY AUTO_INCREMENT, inventory_id BIGINT NOT NULL, movement_type ENUM('receipt','sale','transfer_out','transfer_in','adjustment','recovery') NOT NULL, quantity_delta INT NOT NULL, reference_type VARCHAR(60), reference_id BIGINT, note VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(inventory_id) REFERENCES inventory(id), INDEX ix_movement_ref(reference_type,reference_id));
CREATE TABLE IF NOT EXISTS promotions (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, location_id BIGINT NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, discount_pct DECIMAL(5,2) NOT NULL, units_sold INT, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(location_id) REFERENCES locations(id), CHECK(discount_pct BETWEEN 0 AND 100), CHECK(ends_on >= starts_on));
CREATE TABLE IF NOT EXISTS transport_options (id BIGINT PRIMARY KEY AUTO_INCREMENT, source_location_id BIGINT NOT NULL, destination_location_id BIGINT NOT NULL, cost_per_unit DECIMAL(12,4) NOT NULL, transit_days INT NOT NULL, capacity INT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(source_location_id) REFERENCES locations(id), FOREIGN KEY(destination_location_id) REFERENCES locations(id), CHECK(cost_per_unit >= 0 AND transit_days >= 0 AND capacity >= 0), UNIQUE KEY uq_route(source_location_id,destination_location_id));
CREATE TABLE IF NOT EXISTS recovery_partners (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, partner_type VARCHAR(80) NOT NULL, location_id BIGINT NOT NULL, verification_status ENUM('verified','pending','rejected') NOT NULL DEFAULT 'pending', enabled BOOLEAN NOT NULL DEFAULT FALSE, contact_details VARCHAR(500), FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE IF NOT EXISTS partner_capacities (id BIGINT PRIMARY KEY AUTO_INCREMENT, partner_id BIGINT NOT NULL, capacity_date DATE NOT NULL, capacity_units INT NOT NULL, allocated_units INT NOT NULL DEFAULT 0, FOREIGN KEY(partner_id) REFERENCES recovery_partners(id), UNIQUE KEY uq_partner_day(partner_id,capacity_date), CHECK(capacity_units >= 0 AND allocated_units >= 0 AND allocated_units <= capacity_units));
CREATE TABLE IF NOT EXISTS recovery_rules (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_category VARCHAR(100) NOT NULL, channel VARCHAR(80) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, minimum_days_remaining INT NOT NULL DEFAULT 0, handling_required BOOLEAN NOT NULL DEFAULT TRUE, policy_notes VARCHAR(500), CHECK(minimum_days_remaining >= 0));
CREATE TABLE IF NOT EXISTS model_versions (id BIGINT PRIMARY KEY AUTO_INCREMENT, model_name VARCHAR(120) NOT NULL, version VARCHAR(80) NOT NULL, trained_at DATETIME, training_start DATE, training_end DATE, train_rows INT, test_rows INT, mae DECIMAL(12,4), rmse DECIMAL(12,4), metadata JSON, UNIQUE KEY uq_model_version(model_name,version));
CREATE TABLE IF NOT EXISTS forecasts (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, location_id BIGINT NOT NULL, model_version_id BIGINT, generated_at DATETIME NOT NULL, target_date DATE NOT NULL, predicted_units DECIMAL(12,3) NOT NULL, lower_bound DECIMAL(12,3), upper_bound DECIMAL(12,3), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(location_id) REFERENCES locations(id), FOREIGN KEY(model_version_id) REFERENCES model_versions(id), CHECK(predicted_units >= 0));
CREATE TABLE IF NOT EXISTS anomaly_alerts (id BIGINT PRIMARY KEY AUTO_INCREMENT, fingerprint VARCHAR(180) NOT NULL UNIQUE, anomaly_type VARCHAR(100) NOT NULL, severity ENUM('low','medium','high','critical') NOT NULL, product_id BIGINT, location_id BIGINT, observed_value DECIMAL(14,3), expected_value DECIMAL(14,3), method VARCHAR(120), explanation TEXT, status ENUM('open','investigating','resolved','dismissed') NOT NULL DEFAULT 'open', detected_at DATETIME NOT NULL, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(location_id) REFERENCES locations(id));
CREATE TABLE IF NOT EXISTS redistribution_plans (id BIGINT PRIMARY KEY AUTO_INCREMENT, status ENUM('proposed','approved','rejected','in_progress','completed','cancelled') NOT NULL DEFAULT 'proposed', objective_metadata JSON, created_by BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, approved_at DATETIME, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS redistribution_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, batch_id BIGINT NOT NULL, source_location_id BIGINT NOT NULL, destination_location_id BIGINT NOT NULL, quantity INT NOT NULL, estimated_cost DECIMAL(12,2), transit_days INT, status ENUM('proposed','approved','dispatched','completed','cancelled') NOT NULL DEFAULT 'proposed', FOREIGN KEY(plan_id) REFERENCES redistribution_plans(id), FOREIGN KEY(batch_id) REFERENCES product_batches(id), FOREIGN KEY(source_location_id) REFERENCES locations(id), FOREIGN KEY(destination_location_id) REFERENCES locations(id), CHECK(quantity > 0));
CREATE TABLE IF NOT EXISTS recovery_plans (id BIGINT PRIMARY KEY AUTO_INCREMENT, status ENUM('proposed','approved','rejected','in_progress','completed','cancelled') NOT NULL DEFAULT 'proposed', assumptions JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, approved_at DATETIME);
CREATE TABLE IF NOT EXISTS recovery_allocations (id BIGINT PRIMARY KEY AUTO_INCREMENT, plan_id BIGINT NOT NULL, batch_id BIGINT NOT NULL, partner_id BIGINT, channel VARCHAR(80) NOT NULL, quantity INT NOT NULL, eligibility_status ENUM('eligible','ineligible','requires_review') NOT NULL, status ENUM('proposed','approved','dispatched','completed','cancelled','unallocated') NOT NULL DEFAULT 'proposed', FOREIGN KEY(plan_id) REFERENCES recovery_plans(id), FOREIGN KEY(batch_id) REFERENCES product_batches(id), FOREIGN KEY(partner_id) REFERENCES recovery_partners(id), CHECK(quantity > 0));
CREATE TABLE IF NOT EXISTS simulation_scenarios (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, inputs JSON NOT NULL, results JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS actual_outcomes (id BIGINT PRIMARY KEY AUTO_INCREMENT, outcome_type VARCHAR(80) NOT NULL, reference_id BIGINT, confirmed_units INT NOT NULL, actual_cost DECIMAL(12,2), source VARCHAR(180) NOT NULL, occurred_at DATETIME, recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CHECK(confirmed_units >= 0));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor_user_id BIGINT, action VARCHAR(100) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id VARCHAR(100), before_state JSON, after_state JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_user_id) REFERENCES users(id), INDEX ix_audit_entity(entity_type,entity_id,created_at));
